-- Run after backend/supabase-procurement-acl.sql, and before deploying the backend.
-- Idempotent. Service role bypasses RLS; the anon key cannot read roles.

create table if not exists roles (
  id text primary key,
  name text not null,
  description text,
  data_scope text not null default 'own' check (data_scope in ('own', 'team', 'all')),
  is_system boolean not null default false,
  permissions jsonb not null default '{}'::jsonb,
  is_active boolean not null default true,
  updated_at timestamptz not null default now(),
  updated_by text
);

alter table roles add column if not exists visibility_scope jsonb not null default '{}'::jsonb;

create index if not exists employees_role_idx on employees (role);

alter table roles enable row level security;

